begin;
select plan(16);
insert into auth.users(id,email) values ('fa000000-0000-4000-8000-000000000001','request-test-a@faden.local'),('fa000000-0000-4000-8000-000000000002','request-test-b@faden.local');
insert into public.outfit_requests(id,user_id) values('fa000000-0000-4000-8000-000000000010','fa000000-0000-4000-8000-000000000001');
select ok((select relrowsecurity from pg_class where oid='public.outfit_requests'::regclass),'request RLS enabled');
select ok((select not public from storage.buckets where id='request-inspiration'),'inspiration bucket is private');
select ok(not has_table_privilege('anon','public.outfit_requests','SELECT'),'anonymous request reads denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"fa000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*)::integer from public.outfit_requests where id='fa000000-0000-4000-8000-000000000010'),1,'owner can resume draft');
select throws_ok($$insert into public.outfit_requests(user_id) values('fa000000-0000-4000-8000-000000000002')$$,'42501',null,'cannot create for another user');
select lives_ok($$update public.outfit_requests set draft='{"occasion":"Wedding"}' where id='fa000000-0000-4000-8000-000000000010'$$,'owner can save draft');
select is((select version from public.outfit_requests where id='fa000000-0000-4000-8000-000000000010'),2,'version increases on save');
select throws_ok($$select public.submit_outfit_request('fa000000-0000-4000-8000-000000000010',2)$$,'P0001','Complete all required request details and confirm consent','incomplete submission rejected');
select ok(not has_column_privilege('authenticated','public.outfit_requests','status','UPDATE'),'direct status transition denied');
update public.outfit_requests set draft=jsonb_build_object('occasion','Wedding','garment','Lehenga','budget','25k_50k','measurementMethod','later','expert',true,'consent',true,'eventDate',(current_date+60)::text,'deliveryDate',(current_date+50)::text) where id='fa000000-0000-4000-8000-000000000010';
select lives_ok($$select public.submit_outfit_request('fa000000-0000-4000-8000-000000000010',3)$$,'complete request submits');
select lives_ok($$select public.submit_outfit_request('fa000000-0000-4000-8000-000000000010',3)$$,'submission retry is idempotent');
update public.outfit_requests set draft='{}' where id='fa000000-0000-4000-8000-000000000010';
select is((select draft->>'occasion' from public.outfit_requests where id='fa000000-0000-4000-8000-000000000010'),'Wedding','submitted brief cannot be edited');
select lives_ok($$insert into public.measurement_profiles(user_id,measurements) values('fa000000-0000-4000-8000-000000000001','{"unit":"cm","chest":"90","waist":"70","hips":"95"}')$$,'owner can save private measurements');
select set_config('request.jwt.claims','{"sub":"fa000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::integer from public.measurement_profiles where user_id='fa000000-0000-4000-8000-000000000001'),0,'other users cannot read measurements');
select throws_ok($$select public.submit_outfit_request('fa000000-0000-4000-8000-000000000010',3)$$,'P0001','Request not found','another user cannot submit request');
reset role;
select is((select count(*)::integer from public.outbox_events where aggregate_id='fa000000-0000-4000-8000-000000000010' and event_type='outfit_request.submitted'),1,'submission enqueues one event without measurement payload');
select * from finish();
rollback;
